-- 002_identity
--
-- Decomposes the legacy 137-column `users` table into concern-sized tables, and
-- replaces the two competing RBAC systems with one.
--
-- Legacy primary key values are preserved exactly: user 4417 stays user 4417.
-- That makes migration verification a matter of comparing ids, and makes the
-- reverse-ETL rollback path possible. Hence GENERATED BY DEFAULT AS IDENTITY
-- rather than BIGSERIAL — the ETL supplies ids explicitly, then the sequence is
-- advanced past the maximum (see cmd/cli migrate-data).

BEGIN;

-- ---------------------------------------------------------------------------
-- Core identity: small, hot, read on every authenticated request
-- ---------------------------------------------------------------------------
CREATE TABLE identity.users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id     UUID NOT NULL DEFAULT gen_random_uuid(),
    email         CITEXT NOT NULL,
    password_hash TEXT NOT NULL,
    name          JSONB NOT NULL DEFAULT '{"ar":"","en":""}'::JSONB,
    role          TEXT NOT NULL DEFAULT 'customer',
    status        TEXT NOT NULL DEFAULT 'active'
                  CHECK (status IN ('active','inactive','suspended','pending')),
    language      TEXT NOT NULL DEFAULT 'ar' CHECK (language IN ('ar','en')),
    timezone      TEXT NOT NULL DEFAULT 'Africa/Cairo',
    email_verified_at TIMESTAMPTZ,
    phone         TEXT,
    phone_verified_at TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at    TIMESTAMPTZ
);

-- CITEXT makes the uniqueness case-insensitive, which the legacy
-- utf8mb4_unicode_ci collation gave implicitly. Without it, migrating
-- "Ahmed@x.com" and "ahmed@x.com" would create two accounts that could both
-- log in and neither of which owns the other's orders.
CREATE UNIQUE INDEX users_email_key     ON identity.users (email) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX users_public_id_key ON identity.users (public_id);
CREATE INDEX users_role_status_idx      ON identity.users (role, status) WHERE deleted_at IS NULL;
CREATE INDEX users_created_at_idx       ON identity.users (created_at DESC);

COMMENT ON TABLE  identity.users IS 'Core identity only. Profile, security, MFA, wallet, KYC and payroll live in their own tables.';
COMMENT ON COLUMN identity.users.name IS 'اسم المستخدم // {"ar":"","en":""}';
COMMENT ON COLUMN identity.users.public_id IS 'Exposed in URLs and APIs. The bigint id is internal and sequential, so it leaks user counts.';

CREATE TRIGGER users_touch BEFORE UPDATE ON identity.users
    FOR EACH ROW EXECUTE FUNCTION platform.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Login security
-- ---------------------------------------------------------------------------
CREATE TABLE identity.user_security (
    user_id               BIGINT PRIMARY KEY REFERENCES identity.users(id) ON DELETE CASCADE,
    login_attempts        INT NOT NULL DEFAULT 0,
    locked_until          TIMESTAMPTZ,
    last_login_at         TIMESTAMPTZ,
    last_login_ip         INET,
    last_user_agent       TEXT,
    last_password_change  TIMESTAMPTZ,
    password_change_count INT NOT NULL DEFAULT 0,
    max_login_sessions    INT
);

-- ---------------------------------------------------------------------------
-- Multi-factor authentication
-- ---------------------------------------------------------------------------
-- The legacy row carried two independent implementations side by side
-- (two_factor_* and google2fa_*), so a user could be enrolled in one and not the
-- other with no defined precedence. Only google2fa_* had a live service class
-- behind it, so that is the one that survives.
CREATE TABLE identity.user_mfa (
    user_id        BIGINT PRIMARY KEY REFERENCES identity.users(id) ON DELETE CASCADE,
    totp_secret    BYTEA,
    recovery_codes BYTEA,
    enabled        BOOLEAN NOT NULL DEFAULT false,
    confirmed_at   TIMESTAMPTZ,
    CONSTRAINT mfa_enabled_requires_secret
        CHECK (NOT enabled OR (totp_secret IS NOT NULL AND confirmed_at IS NOT NULL))
);

COMMENT ON COLUMN identity.user_mfa.totp_secret IS
    'Encrypted with pgcrypto. Never selected into application structs except during verification.';

-- ---------------------------------------------------------------------------
-- Federated identities
-- ---------------------------------------------------------------------------
-- Legacy had five nullable columns (facebook_id, google_id, ...). A table makes
-- adding a sixth provider a data change rather than a schema change.
CREATE TABLE identity.user_identities (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT NOT NULL REFERENCES identity.users(id) ON DELETE CASCADE,
    provider    TEXT NOT NULL,
    provider_id TEXT NOT NULL,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (provider, provider_id)
);

CREATE INDEX user_identities_user_idx ON identity.user_identities (user_id);

-- ---------------------------------------------------------------------------
-- Authorization: one model replacing two
-- ---------------------------------------------------------------------------
-- Legacy had admin_roles/admin_permissions/admin_role_permissions AND
-- supplier_roles/supplier_permissions/supplier_role_permissions, plus
-- users.he_can_do_anything and a full_powers table, plus two globally
-- autoloaded PHP helper files. Four sources of truth for one question.
--
-- Here a role is scoped either to the platform or to an organization, and the
-- effective permission set is one query.

CREATE TABLE identity.roles (
    key         TEXT PRIMARY KEY,
    name        JSONB NOT NULL,
    scope       TEXT NOT NULL CHECK (scope IN ('platform','organization')),
    is_system   BOOLEAN NOT NULL DEFAULT false,
    description TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON COLUMN identity.roles.is_system IS
    'System roles cannot be deleted or renamed through the admin UI. super_admin is one.';

CREATE TABLE identity.permissions (
    key         TEXT PRIMARY KEY,
    name        JSONB NOT NULL,
    module      TEXT NOT NULL,
    description TEXT
);

CREATE INDEX permissions_module_idx ON identity.permissions (module);

CREATE TABLE identity.role_permissions (
    role_key       TEXT NOT NULL REFERENCES identity.roles(key) ON DELETE CASCADE,
    permission_key TEXT NOT NULL REFERENCES identity.permissions(key) ON DELETE CASCADE,
    PRIMARY KEY (role_key, permission_key)
);

-- Platform-scoped role assignment (admins, developers, support).
CREATE TABLE identity.user_roles (
    user_id    BIGINT NOT NULL REFERENCES identity.users(id) ON DELETE CASCADE,
    role_key   TEXT NOT NULL REFERENCES identity.roles(key) ON DELETE CASCADE,
    granted_by BIGINT REFERENCES identity.users(id) ON DELETE SET NULL,
    granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, role_key)
);

-- ---------------------------------------------------------------------------
-- Profile
-- ---------------------------------------------------------------------------
CREATE TABLE profile.user_profiles (
    user_id          BIGINT PRIMARY KEY REFERENCES identity.users(id) ON DELETE CASCADE,
    first_name       TEXT,
    last_name        TEXT,
    avatar_url       TEXT,
    date_of_birth    DATE,
    gender           TEXT CHECK (gender IN ('male','female','other')),
    nationality      TEXT,
    bio              TEXT,
    slug             TEXT,
    website          TEXT,
    whatsapp         TEXT,
    telegram         TEXT,
    secondary_email  CITEXT,
    secondary_phone  TEXT,
    meta_description TEXT,
    meta_keywords    TEXT,
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX user_profiles_slug_key ON profile.user_profiles (slug) WHERE slug IS NOT NULL;

CREATE TABLE profile.user_preferences (
    user_id                 BIGINT PRIMARY KEY REFERENCES identity.users(id) ON DELETE CASCADE,
    theme                   TEXT NOT NULL DEFAULT 'light' CHECK (theme IN ('light','dark','auto')),
    notification_channels   JSONB NOT NULL DEFAULT '{"email":true,"sms":false,"push":true}'::JSONB,
    notification_topics     JSONB NOT NULL DEFAULT '{"offers":true,"blog":false,"newsletter":true}'::JSONB,
    marketing_consent       BOOLEAN NOT NULL DEFAULT false,
    data_processing_consent BOOLEAN NOT NULL DEFAULT true,
    terms_accepted_at       TIMESTAMPTZ,
    terms_version           TEXT,
    privacy_accepted_at     TIMESTAMPTZ,
    preferences             JSONB NOT NULL DEFAULT '{}'::JSONB,
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- The legacy schema had seven separate boolean notification columns plus a
-- notification_preferences JSON column. Collapsing them into two JSONB objects
-- means a new channel or topic is a code change, not a migration.

-- ---------------------------------------------------------------------------
-- Compliance: KYC and identity documents
-- ---------------------------------------------------------------------------
CREATE TABLE identity.kyc_records (
    user_id             BIGINT PRIMARY KEY REFERENCES identity.users(id) ON DELETE CASCADE,
    status              TEXT NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending','verified','rejected')),
    national_id         TEXT,
    passport_number     TEXT,
    business_license    TEXT,
    tax_number          TEXT,
    company_name        JSONB,
    business_description JSONB,
    industry            TEXT,
    identity_verified_at TIMESTAMPTZ,
    notes               TEXT,
    reviewed_by         BIGINT REFERENCES identity.users(id) ON DELETE SET NULL,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE identity.kyc_records IS
    'Regulated personal data. Access is permission-gated and every read is audited.';

-- ---------------------------------------------------------------------------
-- Account deletion workflow
-- ---------------------------------------------------------------------------
-- Legacy tracked this across six columns on `users` (want_delete,
-- read_want_delete, wanted_delete_reason, wanted_delete_at, delete_status,
-- admin_response). It is a workflow, so it gets a table.
CREATE TABLE identity.account_deletion_requests (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id        BIGINT NOT NULL REFERENCES identity.users(id) ON DELETE CASCADE,
    status         TEXT NOT NULL DEFAULT 'under_review'
                   CHECK (status IN ('under_review','approved','rejected','deleted','recovered')),
    reason         TEXT,
    admin_response JSONB,
    reviewed_by    BIGINT REFERENCES identity.users(id) ON DELETE SET NULL,
    requested_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    resolved_at    TIMESTAMPTZ
);

CREATE INDEX deletion_requests_status_idx ON identity.account_deletion_requests (status, requested_at);

-- ---------------------------------------------------------------------------
-- Seed roles and permissions
-- ---------------------------------------------------------------------------
INSERT INTO identity.roles (key, name, scope, is_system, description) VALUES
