    ('admin',        '{"ar":"مدير","en":"Administrator"}',          'platform',     true,  'Platform administration'),
    ('support',      '{"ar":"دعم","en":"Support"}',                 'platform',     true,  'Read-mostly support access'),
    ('developer',    '{"ar":"مطور","en":"Developer"}',              'platform',     true,  'Technical diagnostics'),
    ('org_owner',    '{"ar":"مالك","en":"Owner"}',                  'organization', true,  'Full control of one organization'),
    ('org_manager',  '{"ar":"مدير المؤسسة","en":"Manager"}',        'organization', true,  'Day-to-day management'),
    ('org_employee', '{"ar":"موظف","en":"Employee"}',               'organization', true,  'Limited operational access'),
