-- org_owner receives every organization-scoped permission.
INSERT INTO identity.role_permissions (role_key, permission_key)
SELECT 'org_owner', key FROM identity.permissions
WHERE module IN ('catalog','inventory','commerce','billing','org','ingest');

INSERT INTO identity.role_permissions (role_key, permission_key)
SELECT 'org_manager', key FROM identity.permissions
WHERE key IN ('catalog.product.view','catalog.product.create','catalog.product.update',
              'inventory.stock.view','inventory.stock.adjust',
              'commerce.order.view','commerce.order.fulfil','ingest.import.run');

INSERT INTO identity.role_permissions (role_key, permission_key)
SELECT 'org_employee', key FROM identity.permissions
WHERE key IN ('catalog.product.view','inventory.stock.view','commerce.order.view');

COMMIT;
